let started=false,overview=true,ready=false,paused=false,nearby=null,activePanel='',route=[],routeStation=null,world=null,engine=null,joystick={x:0,y:0,active:false},boosting=false;
const state={x:-3,z:8,heading:-.4,speed:0},keys=new Set(),seen=new Set(),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
