function updateSeen(id){if(seen.has(id)||!STATIONS.some(s=>s.id===id))return;seen.add(id);$('visited-count').textContent=String(seen.size).padStart(2,'0');markerEls.get(id).classList.add('discovered');$('voyage-dots').querySelector(`[data-id="${id}"]`).classList.add('seen');if(seen.size===6)toast(choose('Has encontrado las seis señales. Bienvenido a BOIA.','You found all six signals. Welcome to BOIA.'));}
function renderPanel(id){$('panel-content').innerHTML=panelHTML(id,lang,seen);$('panel-content').querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openPanel(b.dataset.open));$('panel-content').querySelectorAll('[data-sail]').forEach(b=>b.onclick=()=>{dialog.close();sailTo(STATIONS.find(s=>s.id===b.dataset.sail));});$('panel-content').querySelectorAll('[data-reset]').forEach(b=>b.onclick=()=>{dialog.close();resetBoat();});$('panel-content').querySelectorAll('[data-camera]').forEach(b=>b.onclick=()=>{dialog.close();toggleCamera();});}
function openPanel(id){activePanel=id;paused=true;stopControls();updateSeen(id);renderPanel(id);if(!dialog.open){lastFocus=document.activeElement;dialog.showModal();}dialog.scrollTop=0;}
dialog.addEventListener('close',()=>{paused=false;activePanel='';stopControls();lastFocus?.focus?.({preventScroll:true});});$('close-panel').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
$('destinations').onclick=()=>openPanel('destinations');$('map-toggle').onclick=()=>openPanel('destinations');$('help').onclick=()=>openPanel('help');$('fallback-menu').onclick=()=>openPanel('destinations');$('language').onclick=()=>{lang=lang==='es'?'en':'es';translate();};$('dock-open').onclick=()=>nearby&&openPanel(nearby.id);
function start(){if(!ready)return;if(!started)$('game-tip').hidden=false;started=true;overview=false;document.body.classList.add('playing');$('welcome').inert=true;$('world').focus({preventScroll:true});}
$('start').onclick=start;
function goHome(){if(dialog.open)dialog.close();stopControls();cancelRoute();state.speed=0;started=false;overview=true;paused=false;document.body.classList.remove('playing');$('welcome').inert=false;$('game-tip').hidden=true;$('dock-prompt').hidden=true;$('start').focus({preventScroll:true});}
$('home').onclick=goHome;document.querySelector('.wordmark').onclick=e=>{e.preventDefault();goHome();};
document.querySelectorAll('[data-home-open]').forEach(b=>b.onclick=()=>openPanel(b.dataset.homeOpen));
function resetBoat(){start();cancelRoute();Object.assign(state,{x:-3,z:8,heading:-.4,speed:0});overview=false;toast(choose('De vuelta a puerto. Rumbo libre.','Back at the harbour. Sail freely.'));}
function toggleCamera(){if(!ready)return;overview=!overview;toast(overview?choose('Vista del archipiélago','Archipelago view'):choose('Cámara a bordo','Onboard camera'));}
$('camera').onclick=toggleCamera;
function cancelRoute(){route=[];routeStation=null;$('navigation-status').hidden=true;if(world)world.destinationRing.visible=false;}
function showRoute(){const name=routeStation?routeStation[lang]:choose('mar abierto','open sea');$('navigation-text').textContent=choose('Piloto automático → ','Autopilot → ')+name;$('navigation-status').hidden=false;}
function sailTo(goal){if(!ready){openPanel(goal.id||'destinations');return;}start();$('game-tip').hidden=true;route=planRoute(state,goal);if(!route.length){toast(choose('Ese punto está en tierra. Elige una boya o toca el mar.','That point is on land. Choose a buoy or tap the sea.'));return;}routeStation=goal.id?goal:null;world.destinationRing.position.set(goal.x,.06,goal.z);world.destinationRing.visible=true;showRoute();}
$('cancel-route').onclick=()=>{cancelRoute();state.speed=0;};
document.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if(dialog.open||e.target.closest?.('input,textarea,select'))return;if(['arrowup','arrowdown','arrowleft','arrowright',' ','w','a','s','d','shift','e','enter','m','r'].includes(key)){if(['enter',' '].includes(key)&&e.target instanceof HTMLButtonElement)return;e.preventDefault();}if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' '].includes(key)){start();cancelRoute();$('game-tip').hidden=true;keys.add(key);}if(key==='shift')keys.add(key);if(e.repeat)return;if(key==='m')openPanel('destinations');if(key==='r')resetBoat();if((key==='e'||key==='enter')&&nearby)openPanel(nearby.id);});document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{stopControls();state.speed=0;});document.addEventListener('visibilitychange',()=>{stopControls();state.speed=0;if(document.hidden&&audioContext)audioContext.suspend();else if(audioOn&&audioContext)audioContext.resume().catch(()=>{});});
function setJoy(e){$('game-tip').hidden=true;const r=$('joystick').querySelector('.stick-base').getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,l=Math.hypot(dx,dy),m=34,scale=l>m?m/l:1;joystick={x:dx*scale/m,y:dy*scale/m,active:true};$('stick-thumb').style.transform=`translate(${dx*scale}px,${dy*scale}px)`;}
$('joystick').addEventListener('pointerdown',e=>{if(!ready||paused||joyPointer!==null||boatControls?.active||e.button!==0)return;e.preventDefault();start();cancelRoute();joyPointer=e.pointerId;$('joystick').setPointerCapture(e.pointerId);setJoy(e);});$('joystick').addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)setJoy(e);});function endJoy(e){if(joyPointer===null||(e&&e.pointerId!==joyPointer))return;const id=joyPointer;joyPointer=null;joystick={x:0,y:0,active:false};$('stick-thumb').style.transform='';if($('joystick').hasPointerCapture(id))$('joystick').releasePointerCapture(id);}for(const name of ['pointerup','pointercancel','lostpointercapture'])$('joystick').addEventListener(name,endJoy);
$('boost').addEventListener('pointerdown',e=>{boosting=true;$('boost').setPointerCapture(e.pointerId);});for(const name of ['pointerup','pointercancel','lostpointercapture'])$('boost').addEventListener(name,()=>boosting=false);
// An original, quiet synthesized house pulse, only after an explicit sound toggle.
let audioOn=false,audioContext=null,audioGain=null,audioTimer=null,beat=0;
function makeAudio(){audioContext=new(window.AudioContext||window.webkitAudioContext)();audioGain=audioContext.createGain();audioGain.gain.value=.13;audioGain.connect(audioContext.destination);audioTimer=setInterval(()=>{if(!audioOn||document.hidden||audioContext.state!=='running')return;const now=audioContext.currentTime;const o=audioContext.createOscillator(),g=audioContext.createGain();o.frequency.setValueAtTime(120,now);o.frequency.exponentialRampToValueAtTime(42,now+.15);g.gain.setValueAtTime(.9,now);g.gain.exponentialRampToValueAtTime(.001,now+.27);o.connect(g);g.connect(audioGain);o.start(now);o.stop(now+.3);if(beat%2===1){const h=audioContext.createOscillator(),hg=audioContext.createGain();h.type='triangle';h.frequency.value=[220,261.63,196,293.66][Math.floor(beat/2)%4];hg.gain.setValueAtTime(.06,now+.1);hg.gain.exponentialRampToValueAtTime(.001,now+.39);h.connect(hg);hg.connect(audioGain);h.start(now+.1);h.stop(now+.4);}beat++;},500);}
$('sound').onclick=async()=>{try{if(!audioContext)makeAudio();audioOn=!audioOn;await(audioOn?audioContext.resume():audioContext.suspend());$('sound').setAttribute('aria-pressed',String(audioOn));$('sound-waves').setAttribute('d',audioOn?'M17 8c2 2 2 6 0 8m3-11c4 4 4 10 0 14':'m17 9 5 6m0-6-5 6');translate();}catch{audioOn=false;toast(choose('El sonido no está disponible en este navegador.','Sound is not available in this browser.'));}};
